text:
Calculation
An account is new on the ET day of its first event in authentication_activity. It is idle if it has no successful event in application_usage for a public application. Public means not flagged internal in rp.service; an application with no row in rp.alias counts as public, because internal applications are the ones registered on purpose and a new partner can go live before it is added.
There are three idle windows:

Ever: no public use at all yet. Keeps falling as accounts age.
14 days: no public use within 14 days of the first event. Final once 14 days have passed.
Same day: no public use by the end of the ET day the account was made. Final the next morning, so it is the one to use for spotting bot days.

Leave out a blank user ID. The user ID "UNKNOWN" counts as one account, as it does in the summary tables (see notes).






NoteExample queries






SQLR


By day:
WITH first_seen AS (
    SELECT
        subject,
        min(CAST(substr(time, 1, 19) AS timestamp)) AS first_ts
    FROM ibm_verify_events_raw.authentication_activity
    WHERE subject &lt;&gt; ''
    GROUP BY subject
),
new_accounts AS (
    SELECT
        subject,
        first_ts,
        -- time is a UTC string; report on ET days
        date(with_timezone(first_ts, 'UTC') AT TIME ZONE 'America/Toronto') AS created_on
    FROM first_seen
),
public_use AS (
    SELECT
        userid,
        min(CAST(substr(time, 1, 19) AS timestamp)) AS first_public_ts
    FROM ibm_verify_events_raw.application_usage
    WHERE result = 'success'
      -- only internal applications are left out; an unmapped one is public
      AND applicationname NOT IN (
          SELECT al.alias
          FROM rp.alias al
          JOIN rp.service s ON al.rp_id = s.rp_id
          WHERE s.is_internal
      )
    GROUP BY userid
)

SELECT
    n.created_on,
    count(*) AS new_accounts,
    count_if(p.userid IS NULL) AS idle_accounts,
    count_if(p.userid IS NULL OR p.first_public_ts &gt; n.first_ts + INTERVAL '14' DAY) AS idle_accounts_14d,
    count_if(p.userid IS NULL OR date(with_timezone(p.first_public_ts, 'UTC') AT TIME ZONE 'America/Toronto') &gt; n.created_on) AS idle_accounts_same_day,
    CAST(count_if(p.userid IS NULL) AS DOUBLE) / count(*) AS idle_rate,
    CAST(count_if(p.userid IS NULL OR p.first_public_ts &gt; n.first_ts + INTERVAL '14' DAY) AS DOUBLE) / count(*) AS idle_rate_14d,
    CAST(count_if(p.userid IS NULL OR date(with_timezone(p.first_public_ts, 'UTC') AT TIME ZONE 'America/Toronto') &gt; n.created_on) AS DOUBLE) / count(*) AS idle_rate_same_day
FROM new_accounts n
LEFT JOIN public_use p ON n.subject = p.userid
-- set the reporting window; see the timespans note in cookbook/notes.qmd
WHERE n.created_on BETWEEN DATE '2026-09-01' AND DATE '2026-09-30'
GROUP BY n.created_on
ORDER BY n.created_on;
Since launch, point in time:
WITH first_seen AS (
    SELECT
        subject,
        min(CAST(substr(time, 1, 19) AS timestamp)) AS first_ts
    FROM ibm_verify_events_raw.authentication_activity
    WHERE subject &lt;&gt; ''
    GROUP BY subject
),
new_accounts AS (
    SELECT
        subject,
        date(with_timezone(first_ts, 'UTC') AT TIME ZONE 'America/Toronto') AS created_on
    FROM first_seen
),
public_use AS (
    SELECT
        userid,
        min(CAST(substr(time, 1, 19) AS timestamp)) AS first_public_ts
    FROM ibm_verify_events_raw.application_usage
    WHERE result = 'success'
      AND applicationname NOT IN (
          SELECT al.alias
          FROM rp.alias al
          JOIN rp.service s ON al.rp_id = s.rp_id
          WHERE s.is_internal
      )
    GROUP BY userid
),
-- accounts made each day, and accounts that first used a public service each day
daily AS (
    SELECT created_on AS day, count(*) AS created, 0 AS activated
    FROM new_accounts
    GROUP BY created_on
    UNION ALL
    SELECT
        date(with_timezone(p.first_public_ts, 'UTC') AT TIME ZONE 'America/Toronto') AS day,
        0 AS created,
        count(*) AS activated
    FROM new_accounts n
    JOIN public_use p ON n.subject = p.userid
    GROUP BY date(with_timezone(p.first_public_ts, 'UTC') AT TIME ZONE 'America/Toronto')
)

SELECT
    day,
    sum(sum(created)) OVER (ORDER BY day) AS accounts,
    sum(sum(created) - sum(activated)) OVER (ORDER BY day) AS idle_accounts
FROM daily
GROUP BY day
ORDER BY day;


By day:
first_seen &lt;- tbl(con, in_schema("ibm_verify_events_raw", "authentication_activity")) |&gt;
  filter(!is.na(subject), subject != "") |&gt;
  mutate(ts = sql("CAST(substr(time, 1, 19) AS timestamp)")) |&gt;
  group_by(subject) |&gt;
  summarise(first_ts = min(ts, na.rm = TRUE), .groups = "drop") |&gt;
  # time is a UTC string; report on ET days
  mutate(created_on = sql("date(with_timezone(first_ts, 'UTC') AT TIME ZONE 'America/Toronto')"))

# only internal applications are left out; an unmapped one is public
internal_apps &lt;- tbl(con, in_schema("rp", "alias")) |&gt;
  inner_join(tbl(con, in_schema("rp", "service")), by = "rp_id") |&gt;
  filter(is_internal) |&gt;
  select(applicationname = alias)

public_use &lt;- tbl(con, in_schema("ibm_verify_events_raw", "application_usage")) |&gt;
  filter(result == "success") |&gt;
  anti_join(internal_apps, by = "applicationname") |&gt;
  mutate(ts = sql("CAST(substr(time, 1, 19) AS timestamp)")) |&gt;
  group_by(userid) |&gt;
  summarise(first_public_ts = min(ts, na.rm = TRUE), .groups = "drop") |&gt;
  mutate(first_public_day = sql("date(with_timezone(first_public_ts, 'UTC') AT TIME ZONE 'America/Toronto')"))

first_seen |&gt;
  # set the reporting window; see the timespans note in cookbook/notes.qmd
  filter(
    created_on &gt;= as.Date("2026-09-01"),
    created_on &lt;= as.Date("2026-09-30")
  ) |&gt;
  left_join(public_use, by = c("subject" = "userid")) |&gt;
  mutate(
    idle = is.na(first_public_ts),
    idle_14d = is.na(first_public_ts) | first_public_ts &gt; sql("first_ts + INTERVAL '14' DAY"),
    idle_same_day = is.na(first_public_ts) | first_public_day &gt; created_on
  ) |&gt;
  group_by(created_on) |&gt;
  summarise(
    new_accounts = n(),
    idle_accounts = sum(as.integer(idle), na.rm = TRUE),
    idle_accounts_14d = sum(as.integer(idle_14d), na.rm = TRUE),
    idle_accounts_same_day = sum(as.integer(idle_same_day), na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  mutate(
    idle_rate = as.numeric(idle_accounts) / new_accounts,
    idle_rate_14d = as.numeric(idle_accounts_14d) / new_accounts,
    idle_rate_same_day = as.numeric(idle_accounts_same_day) / new_accounts
  ) |&gt;
  arrange(created_on)
Since launch, point in time:
first_seen &lt;- tbl(con, in_schema("ibm_verify_events_raw", "authentication_activity")) |&gt;
  filter(!is.na(subject), subject != "") |&gt;
  mutate(ts = sql("CAST(substr(time, 1, 19) AS timestamp)")) |&gt;
  group_by(subject) |&gt;
  summarise(first_ts = min(ts, na.rm = TRUE), .groups = "drop") |&gt;
  mutate(created_on = sql("date(with_timezone(first_ts, 'UTC') AT TIME ZONE 'America/Toronto')"))

internal_apps &lt;- tbl(con, in_schema("rp", "alias")) |&gt;
  inner_join(tbl(con, in_schema("rp", "service")), by = "rp_id") |&gt;
  filter(is_internal) |&gt;
  select(applicationname = alias)

public_use &lt;- tbl(con, in_schema("ibm_verify_events_raw", "application_usage")) |&gt;
  filter(result == "success") |&gt;
  anti_join(internal_apps, by = "applicationname") |&gt;
  mutate(ts = sql("CAST(substr(time, 1, 19) AS timestamp)")) |&gt;
  group_by(userid) |&gt;
  summarise(first_public_ts = min(ts, na.rm = TRUE), .groups = "drop") |&gt;
  mutate(first_public_day = sql("date(with_timezone(first_public_ts, 'UTC') AT TIME ZONE 'America/Toronto')"))

# accounts made each day, and accounts that first used a public service each day
created &lt;- first_seen |&gt;
  count(day = created_on, name = "created") |&gt;
  mutate(activated = 0L)

activated &lt;- first_seen |&gt;
  inner_join(public_use, by = c("subject" = "userid")) |&gt;
  count(day = first_public_day, name = "activated") |&gt;
  mutate(created = 0L)

union_all(created, activated) |&gt;
  group_by(day) |&gt;
  summarise(
    created = sum(created, na.rm = TRUE),
    activated = sum(activated, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  window_order(day) |&gt;
  mutate(
    accounts = cumsum(created),
    idle_accounts = cumsum(created - activated)
  ) |&gt;
  select(day, accounts, idle_accounts) |&gt;
  arrange(day)

Calculation
Sum the latest year-to-date unique users across every application (from events_app_login_counts), then divide by the latest CanadaLogin-wide year-to-date unique users (from events_auth_total_logins). Both inputs are cumulative ytd_unique_users fields, so take the latest value per source rather than summing across days.






NoteExample queries






SQLR


WITH app_latest AS (
    SELECT
        application_name,
        ytd_unique_users,
        ROW_NUMBER() OVER (
            PARTITION BY application_name
            ORDER BY from_date DESC
        ) AS rn
    FROM ibm_verify_events_transformed.events_app_login_counts
),

app_total AS (
    SELECT SUM(ytd_unique_users) AS sum_app_unique_users
    FROM app_latest
    WHERE rn = 1
),

overall_total AS (
    SELECT ytd_unique_users AS overall_unique_users
    FROM ibm_verify_events_transformed.events_auth_total_logins
    ORDER BY from_date DESC
    LIMIT 1
)

SELECT
    CAST(app_total.sum_app_unique_users AS DOUBLE)
        / NULLIF(overall_total.overall_unique_users, 0) AS applications_per_credential
FROM app_total
CROSS JOIN overall_total;


sum_app_unique_users &lt;- tbl(con, in_schema("ibm_verify_events_transformed", "events_app_login_counts")) |&gt;
  group_by(application_name) |&gt;
  slice_max(
    from_date,
    n = 1,
    with_ties = FALSE
  ) |&gt;
  ungroup() |&gt;
  summarise(
    sum_app_unique_users = sum(as.double(ytd_unique_users), na.rm = TRUE)
  ) |&gt;
  pull(sum_app_unique_users)

overall_unique_users &lt;- tbl(con, in_schema("ibm_verify_events_transformed", "events_auth_total_logins")) |&gt;
  slice_max(
    from_date,
    n = 1,
    with_ties = FALSE
  ) |&gt;
  pull(ytd_unique_users)

sum_app_unique_users / overall_unique_users

Notes
Sign-up email checks have no user. Email OTP events with performedby_type = "api" come from “GC Sign in API Client” and never carry a subject. They appear to be the email check during sign-up, before the account exists, and they are most Email OTP “sent” events. The summary table counts them in email_otp, which is why email_otp is not a sign-in factor.
OTP factors log a “sent” event too. See events_mfa_activity for how to count usage and success rates.
Example. Distinct users who passed each factor on an ET day:
tbl(con, in_schema("ibm_verify_events_raw", "mfa_activity")) |&gt;
  # partitions are UTC days, so read the next one too for the ET evening
  filter(year == "2026", month == "09", day %in% c("15", "16")) |&gt;
  mutate(et_day = sql("date(with_timezone(CAST(substr(time, 1, 19) AS timestamp), 'UTC') AT TIME ZONE 'America/Toronto')")) |&gt;
  filter(
    et_day == as.Date("2026-09-15"), result == "success",
    !is.na(subject), !subject %in% c("", "UNKNOWN")
  ) |&gt;
  group_by(mfamethod) |&gt;
  summarise(unique_users = n_distinct(subject))

Notes
Failed events rarely have a user. Almost all failures have userid = "UNKNOWN".
Flow Application is CanadaLogin’s own. Almost every new account reaches it right after sign-up, which suggests it is the sign-up flow. It is an internal application in rp.service, so exclude internal applications when the question is about partner services.
Join to relying parties after, not before, aggregating. See Joining through the lookup.
Example. Distinct users who reached each application on an ET day:
tbl(con, in_schema("ibm_verify_events_raw", "application_usage")) |&gt;
  # partitions are UTC days, so read the next one too for the ET evening
  filter(year == "2026", month == "09", day %in% c("15", "16")) |&gt;
  mutate(et_day = sql("date(with_timezone(CAST(substr(time, 1, 19) AS timestamp), 'UTC') AT TIME ZONE 'America/Toronto')")) |&gt;
  filter(
    et_day == as.Date("2026-09-15"), result == "success",
    !is.na(userid), !userid %in% c("", "UNKNOWN")
  ) |&gt;
  group_by(applicationname) |&gt;
  summarise(unique_users = n_distinct(userid))

Notes
Some evaluations have no risk level. Almost all of them have policy_action = "ACTION_REDIRECT". The summary table counts them in total_invocations but in no level.
Location columns are named differently here. They are city, region, and country, not the geoip__ columns of the other three tables.
Example. Evaluations and distinct users by risk level on an ET day:
tbl(con, in_schema("ibm_verify_events_raw", "adaptive_access")) |&gt;
  # partitions are UTC days, so read the next one too for the ET evening
  filter(year == "2026", month == "09", day %in% c("15", "16")) |&gt;
  mutate(et_day = sql("date(with_timezone(CAST(substr(time, 1, 19) AS timestamp), 'UTC') AT TIME ZONE 'America/Toronto')")) |&gt;
  filter(
    et_day == as.Date("2026-09-15"),
    !is.na(userid), !userid %in% c("", "UNKNOWN")
  ) |&gt;
  group_by(risk_level) |&gt;
  summarise(evaluations = n(), unique_users = n_distinct(userid))

Notes
When an account first appears. A new account’s first event is almost always a successful user_password. This suggests the sign-up flow signs a new account in as soon as the password is set, with no MFA required. A few start with a successful token-exchange instead, possibly migrated accounts. Both readings are observed, not confirmed with the sign-up flow’s owners.
Failed password attempts on unknown usernames have no user. They log subject = "UNKNOWN" and realm = "UNKNOWN".
Example. Distinct users with an authentication event on an ET day:
tbl(con, in_schema("ibm_verify_events_raw", "authentication_activity")) |&gt;
  # partitions are UTC days, so read the next one too for the ET evening
  filter(year == "2026", month == "09", day %in% c("15", "16")) |&gt;
  mutate(et_day = sql("date(with_timezone(CAST(substr(time, 1, 19) AS timestamp), 'UTC') AT TIME ZONE 'America/Toronto')")) |&gt;
  filter(
    et_day == as.Date("2026-09-15"),
    !is.na(subject), !subject %in% c("", "UNKNOWN")
  ) |&gt;
  summarise(unique_users = n_distinct(subject))
This is one less than events_auth_total_logins.unique_users on days with an "UNKNOWN" event, because the summary table counts it.

Grouping topics into categories
Topic text is free-form and grows over time, so the Support dashboard groups it into a handful of categories with a hand-kept map: the topic-categories.csv lookup first, then the patterns in topic_patterns in that dashboard’s R/metrics.R, then “Other”. Use that map rather than writing another one.
Count a call once per category, not once per topic: a call that touched two topics in the same category counts once in it. So apply the map to the call and topic rows before counting, not to the topic counts above:
categories &lt;- readr::read_csv(
  "https://raw.githubusercontent.com/cds-snc/canadalogin-reporting-dashboards/main/dashboards/support/topic-categories.csv",
  show_col_types = FALSE
)

call_topics |&gt;                       # one row per call_no and call_topic
  left_join(categories, by = c("call_topic" = "topic")) |&gt;
  mutate(category = coalesce(category, "Other")) |&gt;
  distinct(call_no, category) |&gt;
  count(category, name = "calls")
This uses the lookup only; topics it does not list fall to “Other” here, where the dashboard would first try its patterns.

Calculation
Sum total_logins over the selected reporting period, grouped by application.
By service. A service can have several applications, one per name IBM Verify knows it by. To report a service, map each application to its service through rp.alias, then sum. SSO events are counts, so they add up across a service’s applications; unique users do not (see Cumulative Unique Users by Application). Keep an application with no rp.alias row under its own name rather than dropping it, so the service totals still add up to the application totals.






NoteExample queries






SQLR


By application:
SELECT
  application_name,
  SUM(total_logins) AS total_sso_events
FROM   ibm_verify_events_transformed.events_app_login_counts
-- set the reporting window; see the timespans note in cookbook/notes.qmd
WHERE  CAST(from_date AS DATE) BETWEEN DATE '2026-01-01' AND DATE '2026-05-28'
-- optionally filter out internal applications; see the internal applications
-- note in cookbook/notes.qmd
  AND application_name NOT IN (
      SELECT al.alias
      FROM   rp.alias al
      JOIN   rp.service s ON al.rp_id = s.rp_id
      WHERE  s.is_internal
  )
GROUP  BY application_name
ORDER  BY total_sso_events DESC;
By service:
SELECT
  COALESCE(s.service_name_en, a.application_name) AS service,
  SUM(a.total_logins) AS total_sso_events
FROM   ibm_verify_events_transformed.events_app_login_counts a
-- left joins keep an application with no alias row, under its own name
LEFT JOIN rp.alias al ON a.application_name = al.alias
LEFT JOIN rp.service s ON al.rp_id = s.rp_id
-- set the reporting window; see the timespans note in cookbook/notes.qmd
WHERE  CAST(a.from_date AS DATE) BETWEEN DATE '2026-01-01' AND DATE '2026-05-28'
  AND  NOT COALESCE(s.is_internal, FALSE)
-- aggregate after the join: several applications can map to one service
GROUP  BY COALESCE(s.service_name_en, a.application_name)
ORDER  BY total_sso_events DESC;


By application:
internal_apps &lt;- tbl(con, in_schema("rp", "alias")) |&gt;
  inner_join(tbl(con, in_schema("rp", "service")), by = "rp_id") |&gt;
  filter(is_internal) |&gt;
  select(application_name = alias)

tbl(con, in_schema("ibm_verify_events_transformed", "events_app_login_counts")) |&gt;
  # set the reporting window; see the timespans note in cookbook/notes.qmd
  filter(
    as.Date(from_date) &gt;= as.Date("2026-01-01"),
    as.Date(from_date) &lt;= as.Date("2026-05-28")
  ) |&gt;
  # optionally filter out internal applications; see the internal applications
  # note in cookbook/notes.qmd
  anti_join(internal_apps, by = "application_name") |&gt;
  group_by(application_name) |&gt;
  summarise(
    total_sso_events = sum(total_logins, na.rm = TRUE)
  ) |&gt;
  arrange(desc(total_sso_events))
By service:
services &lt;- tbl(con, in_schema("rp", "alias")) |&gt;
  inner_join(tbl(con, in_schema("rp", "service")), by = "rp_id") |&gt;
  select(application_name = alias, service_name_en, is_internal)

tbl(con, in_schema("ibm_verify_events_transformed", "events_app_login_counts")) |&gt;
  # set the reporting window; see the timespans note in cookbook/notes.qmd
  filter(
    as.Date(from_date) &gt;= as.Date("2026-01-01"),
    as.Date(from_date) &lt;= as.Date("2026-05-28")
  ) |&gt;
  # a left join keeps an application with no alias row, under its own name
  left_join(services, by = "application_name") |&gt;
  filter(!coalesce(is_internal, FALSE)) |&gt;
  # aggregate after the join: several applications can map to one service
  mutate(service = coalesce(service_name_en, application_name)) |&gt;
  group_by(service) |&gt;
  summarise(
    total_sso_events = sum(total_logins, na.rm = TRUE)
  ) |&gt;
  arrange(desc(total_sso_events))

If you need a window we do not have
The Data and Research team cannot pull an ad hoc unique-user count for a custom date range. What they can do, given a legitimate business need, is add a new standing window to the pipeline so it is counted from then on. Before asking, know that:

adding a window takes weeks, not days or hours;
the new figure starts on the day it goes live, and nothing before that can be filled in;
the window must be 90 days or shorter, for the reasons above.

For the analyst-facing details, see the Cumulative Unique Users metric and the auth_total_logins catalog entry.
